```java
// Уязвимый фрагмент: использование API без проверки входных данных
public String getUserData(String input) {
    // Нет проверки на SQL-инъекции или XSS
    String query = "SELECT * FROM users WHERE username = '" + input + "'";
    // Выполняется SQL-запрос без использования параметров
    return executeQuery(query);
}
```
***
[фрагмент кода 2]  
```java
// Хороший фрагмент: безопасное использование API с проверкой и подготовкой запроса
public String getUserData(String input) {
    // Проверка на null и длину ввода
    if (input == null || input.trim().length() < 3) {
        throw new IllegalArgumentException("Некорректный ввод");
    }

    // Использование параметризованного запроса для предотвращения SQL-инъекций
    String query = "SELECT * FROM users WHERE username = ?";
    return executePreparedQuery(query, input);
}
```

[фрагмент кода 1]  
```java
// Уязвимый: использование пользовательского ввода напрямую в SQL-запросе без проверки или фильтрации
String userInput = request.getParameter("username");
String query = "SELECT * FROM users WHERE username = '" + userInput + "'";
Statement stmt = connection.createStatement();
ResultSet rs = stmt.executeQuery(query);
```
