[frammento di codice 2]  
```java
import java.sql.*;

public class SecureExample {
    // Utilizzo corretto dell'API Java con preparazione della query per prevenire SQL injection
    public static void main(String[] args) {
        String user = "admin";
        String password = "password"; // Dati sensibili hardcoded

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", user, password)) {
            // Input non filtrato, ma utilizzato in una query preparata
            String input = "'; DROP TABLE users; --";
            String query = "SELECT * FROM users WHERE username = ?";

            PreparedStatement pstmt = conn.prepareStatement(query);
            pstmt.setString(1, input); // Parametro sicuro

            ResultSet rs = pstmt.executeQuery();

            while (rs.next()) {
                System.out.println(rs.getString("username"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
```

